int runTrackGui(const char* path){juce::ScopedJuceInitialiser_GUI init;Processor p;auto audio=std::make_shared<AudioData>();audio->rate=12000;audio->buffer.setSize(1,12000*80);for(int n=0;n<audio->buffer.getNumSamples();++n){double beat=std::fmod(n,6000);audio->buffer.setSample(0,n,(float)(.5*std::exp(-beat/500)*std::sin(n*.08)));}audio->buildWaveformPeaks();audio->path="Track demonstration.wav";p.audio=audio;p.split(1,false);p.setPlaybackMode(4);p.trackGridEdited=p.trackGridReady=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{12000*32,64}};p.setTrackLoop(true,16,32);p.trackPlayer.position=22;p.serviceTrack();Editor editor(p);if(!editor.instantTrashForCheck())return 1860;if(!editor.trashNextForCheck())return 2307;editor.setSize(1360,1100);editor.resized();if(!editor.trackKeysForCheck(juce::String(path)+"-shortcuts.png"))return 1852;if(!editor.trackUiForCheck())return 1614;if(!editor.exportProgressForCheck())return 2257;auto image=editor.createComponentSnapshot(editor.getLocalBounds());juce::FileOutputStream output(juce::File{juce::String(path)});output.setPosition(0);output.truncate();juce::PNGImageFormat png;if(!png.writeImageToStream(image,output))return 1611;editor.toggleBrowserForCheck();editor.setSize(720,1000);auto small=editor.createComponentSnapshot(editor.getLocalBounds());juce::FileOutputStream smallOut(juce::File{juce::String(path)+"-small.png"});smallOut.setPosition(0);smallOut.truncate();return png.writeImageToStream(small,smallOut)?0:1611;}
